do $$
declare v_orphans int;
begin
  select count(*) into v_orphans from public.passport_matches
   where season = 2010 and stadium is not null and venue_id is null;
  if v_orphans > 0 then
    raise exception 'ha % partidas de 2010 com estadio sem venue_id -- rode bragantino_passport_venues_seed.sql', v_orphans;
  end if;
end $$;
